#!/usr/bin/env python3
from pathlib import Path
import json
import shutil
import subprocess
from datetime import datetime

ROOT = Path.home() / "tennis-totals-lab"

if not ROOT.exists():
    raise SystemExit("[ERROR] No encuentro ~/tennis-totals-lab")

MAIN = ROOT / "src/main.js"
CENSO = ROOT / "src/engine/censo.js"
LABBANK = ROOT / "src/ui/labBankV068.js"
PACKAGE = ROOT / "package.json"
PACKAGE_LOCK = ROOT / "package-lock.json"

required = [MAIN, CENSO, LABBANK, PACKAGE]
missing = [str(p) for p in required if not p.exists()]
if missing:
    raise SystemExit("[ERROR] Faltan archivos: " + ", ".join(missing))

stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
backup = ROOT / f".v0610-backup-{stamp}"
backup.mkdir(parents=True, exist_ok=True)

for path in required + ([PACKAGE_LOCK] if PACKAGE_LOCK.exists() else []):
    rel = path.relative_to(ROOT)
    target = backup / rel
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(path, target)

print(f"[OK] Backup: {backup}")

